/**
 * GPU-driven culling for `IndirectBatchedMesh` with matrix-based reference positions.
 *
 * **Architecture**
 * - Optimized for `IndirectBatchedMesh` with per-instance matrices
 * - Two-pass block compaction algorithm for efficient parallel writes
 * - Supports both ref-position and matrix-based culling
 * - Per-geometry bounding sphere tests (reads from mesh geometry info)
 * - Writes survivor IDs for indirect instanced draw
 *
 * **Limitations**
 * - **Transparency is not supported**: IndirectBatchedMesh does not support transparent materials.
 *   Use opaque materials only. Depth sorting is not available.
 *
 * **Block Compaction Algorithm**
 * 1. **Count Pass**: Each instance atomically increments its block counter if visible
 * 2. **Prefix Sum**: CPU computes block offsets (serial over blocks, parallel within)
 * 3. **Scatter Pass**: Each visible instance writes to its block's allocated slot
 *
 * **Matrix vs Position Mode**
 * - **Position Mode** (default): Uses `refPosition`/`refNormal` arrays
 * - **Matrix Mode** (via `bindMatricesAsReference()`): Extracts position from matrices
 *   - Enables per-geometry bounding sphere culling
 *   - Ideal for `IndirectBatchedMesh` integration
 *
 * **LOD System**
 * - **Purpose**: Reduce draw density smoothly with distance by keeping each instance with probability `pKeep`.
 * - **Near/Far**: `lodNear` defines where LOD begins. `lodFar` defines where range mode reaches full falloff.
 * - **Modes** (`lodMode`):
 *   - **Disabled (`LOD_MODE_DISABLED`)**: LOD sampling is off.
 *   - **Range (`LOD_MODE_RANGE`)**: Smoothstep falloff between `lodNear` and `lodFar`.
 *     `pKeep = 1 - smoothstep( lodNear, lodFar, d )`
 *   - **Exp (`LOD_MODE_EXP`)**: Exponential density falloff starting at `lodNear`.
 *     `pKeep = exp( -density^2 * (d - lodNear)^2 )`
 *     Note: `lodNear` shifts the start of the exp curve; increasing it delays the falloff.
 * - **Density Parameter**: `lodDensity` acts as exp density (smaller = slower decay).
 * - **Sampling**: Each instance is kept if `hash(instanceId) < pKeep`, giving stable stochastic thinning.
 * - **Compatibility**: Internally computes `stepF = sqrt(1 / max(pKeep, eps))` for legacy outputs.
 *
 * **Integration with IndirectBatchedMesh**
 * ```js
 * import { IndirectBatchedMesh, ComputeBatchCulling, indirectBatch } from '@three-blocks/core';
 *
 * // Create batched mesh
 * const count = 10000;
 * const mesh = new IndirectBatchedMesh(count, 50000, 150000, material);
 * mesh.frustumCulled = false; // Disable CPU culling
 *
 * // Add geometries and instances
 * const sphereId = mesh.addGeometry(new SphereGeometry(1, 16, 16));
 * for (let i = 0; i < count; i++) {
 *   const id = mesh.addInstance(sphereId);
 *   const matrix = new Matrix4();
 *   matrix.makeTranslation(
 *     Math.random() * 100 - 50,
 *     Math.random() * 100 - 50,
 *     Math.random() * 100 - 50
 *   );
 *   mesh.setMatrixAt(id, matrix);
 * }
 *
 * // Setup material with indirect batch node
 * material.positionNode = Fn(() => {
 *   indirectBatch(mesh).toStack();
 *   return positionLocal;
 * })();
 *
 * // Create culler
 * const culler = new ComputeBatchCulling({
 *   renderer,
 *   count,
 *   indexCount: sphereGeometry.index.count,
 *   enabled: true
 * });
 *
 * // Bind mesh matrices as culling reference
 * culler.bindMatricesAsReference(mesh);
 * culler.attachGeometry(mesh.geometry);
 * culler.attachMesh(mesh);
 *
 * // Render loop
 * function animate() {
 *   culler.setCameraUniforms(camera);
 *   culler.update();  // GPU culling
 *   renderer.render(scene, camera);
 * }
 * ```
 *
 * @class ComputeBatchCulling
 * @short GPU culling for IndirectBatchedMesh that compacts survivors and updates indirect draw args from ref positions or matrices.
 * @category Compute
 * @tags WebGPU
 * @see IndirectBatchedMesh
 * @see ComputeInstanceCulling
 */
export class ComputeBatchCulling {
    /**
     * Create a GPU batch culler optimized for IndirectBatchedMesh.
     *
     * @param {Object} options Configuration options.
     * @param {THREE.WebGPURenderer} options.renderer WebGPU renderer instance.
     * @param {number} options.count Total number of instances to test.
     * @param {THREE.StorageBufferAttribute} [options.refPosition] Reference positions (vec3) - optional if using matrices.
     * @param {THREE.StorageBufferAttribute} [options.refNormal] Reference normals (vec3) - optional if using matrices.
     * @param {number} options.indexCount Index count per geometry for indirect draw args.
     * @param {boolean} [options.enabled=true] Enable frustum culling.
     * @param {number} [options.frustumPadXY=0.2] Frustum padding in XY directions.
     * @param {number} [options.frustumPadZNear=0.0] Frustum padding at near plane.
     * @param {number} [options.frustumPadZFar=0.2] Frustum padding at far plane.
     */
    constructor(options: {
        renderer: THREE.WebGPURenderer;
        count: number;
        refPosition?: THREE.StorageBufferAttribute;
        refNormal?: THREE.StorageBufferAttribute;
        indexCount: number;
        enabled?: boolean;
        frustumPadXY?: number;
        frustumPadZNear?: number;
        frustumPadZFar?: number;
    });
    renderer: THREE.WebGPURenderer;
    REF_COUNT: number;
    geometryCount: number;
    geometryRanges: any;
    indexed: boolean;
    _refPosFallbackSSBO: any;
    _refNrmFallbackSSBO: any;
    refPosSSBO: any;
    refNrmSSBO: any;
    refPosNode: any;
    refNrmNode: any;
    outVisSSBO: any;
    outVisNode: any;
    useMatrixRef: any;
    _customMatrixFn: Function;
    _matricesFallbackSB: any;
    matricesSB: any;
    matricesNode: any;
    BLOCK_SIZE: number;
    NUM_BLOCKS: number;
    blockCountsSSBO: any;
    blockOffsetsSSBO: any;
    blockCountsNode: any;
    blockOffsetsNode: any;
    _linearIdSSBO: any;
    _linearIdNode: any;
    _outIdSSBO: any;
    _outIdNode: any;
    _indirect: any;
    geometryRangesSSBO: any;
    geometryRangesNode: any;
    geometryCountsSSBO: any;
    geometryCountsNode: any;
    geometryOffsetsSSBO: any;
    geometryOffsetsNode: any;
    geometryHeadsSSBO: any;
    geometryHeadsNode: any;
    geomAllocHeadSSBO: any;
    geomAllocHeadNode: any;
    _multiIndirect: any;
    lodNear: any;
    nearRadius: any;
    maxStep: any;
    lodFar: any;
    lodMode: any;
    lodDensity: any;
    falloffExp: any;
    camPos: any;
    enabled: any;
    camView: any;
    camProj: any;
    frustumPadXY: any;
    frustumPadZNear: any;
    frustumPadZFar: any;
    initialized: boolean;
    geometryAttached: any;
    meshAttached: any;
    /**
     * Update camera uniforms for frustum culling.
     * Call before `update()` each frame.
     *
     * @param {THREE.Camera} camera Active camera for culling tests.
     */
    setCameraUniforms(camera: THREE.Camera): void;
    /**
     * Attach culling controls to a GUI folder.
     * Compatible with lil-gui, dat.gui, and Three.js Inspector.
     *
     * @param {Object} folder GUI folder instance (e.g., from lil-gui or renderer.inspector.createParameters()).
     */
    attachGUI(folder: any): void;
    _guiFolder: any;
    /**
     * Detach and destroy the GUI folder.
     */
    disposeGUI(): void;
    buildCompute(): void;
    drawStruct: any;
    multiDrawStruct: any;
    multiDrawRaw: any;
    initAllK: any;
    clearVis: any;
    clearBlockCounts: any;
    countBlocks: any;
    clearArgs: any;
    prefixBlocks: any;
    scatter: any;
    clearGeomCounts: any;
    clearGeomHeads: any;
    clearGeomAllocHead: any;
    scatterByGeometry: any;
    writeMultiIndirect: any;
    /**
     * Initialize GPU buffers (called automatically on first update).
     * @private
     */
    private init;
    /**
     * Execute GPU culling with two-pass block compaction.
     * Must be called every frame before rendering.
     */
    update(): Promise<void>;
    /**
     * Attach geometry to receive indirect draw args.
     *
     * @param {THREE.BufferGeometry} geometry Target geometry for indirect rendering.
     */
    attachGeometry(geometry: THREE.BufferGeometry): void;
    /**
     * Attach mesh and configure survivor buffer.
     *
     * @param {THREE.Mesh} mesh Target mesh instance.
     */
    attachMesh(mesh: THREE.Mesh): void;
    /**
     * Override the matrix used for culling (e.g., animation texture).
     * @param {Function|null} resolverFn Function receiving { i, baseMatrix, gid } and returning a mat4 node.
     * @returns {this}
     */
    setReferenceMatrixNode(resolverFn: Function | null): this;
    /**
     * Bind mesh matrices as culling reference (enables matrix mode).
     * Extracts positions from instance matrices and enables per-geometry sphere tests.
     * Automatically called by `IndirectBatchedMesh` when culling is enabled.
     *
     * @param {IndirectBatchedMesh} mesh Mesh with `matricesSB` storage buffer.
     * @throws {Error} If mesh doesn't have `matricesSB`.
     */
    bindMatricesAsReference(mesh: IndirectBatchedMesh): void;
    geometryIdSB: any;
    geometryIdNode: any;
    geometrySpheresSB: any;
    geometrySpheresNode: any;
    /**
     * Read back indirect draw arguments from GPU (debug/stats).
     *
     * @returns {Promise<Uint32Array>} Array of [indexCount, instanceCount, firstIndex, baseVertex, firstInstance].
     */
    readIndirectArgs(): Promise<Uint32Array>;
    /**
     * Read back surviving instance IDs from GPU (debug/analysis).
     *
     * @returns {Promise<Uint32Array>} Array of survivor instance indices.
     */
    readSurvivorIndicesAsync(): Promise<Uint32Array>;
    /**
     * Get indirect draw buffer.
     * @type {THREE.IndirectStorageBufferAttribute}
     * @readonly
     */
    readonly get indirect(): THREE.IndirectStorageBufferAttribute;
    /**
     * Get survivor ID buffer.
     * @type {THREE.StorageBufferAttribute}
     * @readonly
     */
    readonly get outIdSSBO(): THREE.StorageBufferAttribute;
    /**
     * Get survivor ID storage node (TSL).
     * @type {StorageNode}
     * @readonly
     */
    readonly get outIdNode(): StorageNode;
    /**
     * Dispose of GPU resources.
     */
    dispose(): void;
}
